    &mut self,
    origin: Point<Pixels>,
    space: impl Into<Size<AvailableSpace>>,
    f: impl FnOnce(&mut Window, &mut App) -> E,
) -> (E::RequestLayoutState, E::PrepaintState)
where
    E: Element,
{
